def is_subsequence(seq, b):
    it = iter(b)
    return all(x in it for x in seq)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    a = list(map(int, data[2:2+n]))
    b = list(map(int, data[2+n:2+n+m]))

    count = 0
    for d in range(-m, m+1):
        c = [ai + d for ai in a]
        if is_subsequence(c, b):
            count += 1

    print(count)

if __name__ == "__main__":
    main()
